import math
import numpy as np

def strategy(hist, state, pos, ind):
    # Clean up state if flat (trade ended)
    if pos == 0:
        if 'entry_price' in state:
            del state['entry_price']
            del state['entry_atr']

        # Entry conditions
        # Breakout: current high > highest high of prior 48 bars
        highest_prior_48 = ind.highest(hist.high, 48)[-2]
        breakout = hist.high[-1] > highest_prior_48

        # Trend filter: completed 1h candle close > its 20-period EMA
        htf = hist.htf(60)
        ema_20 = ind.ema(htf.close, 20)
        trend_ok = htf.close[-1] > ema_20[-1]

        if breakout and trend_ok:
            # Enter long at 50% equity
            target = 0.5
            entry_price = hist.close[-1]          # signal bar close
            entry_atr = ind.atr(hist, 14)[-1]     # ATR on signal bar
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            take = entry_price + 2 * entry_atr    # TP at 2 ATR
            return {"target": target, "stop": None, "take": take}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    elif pos > 0:
        # In a long trade – check bearish breakdown
        lowest_prior_48 = ind.lowest(hist.low, 48)[-2]
        breakdown = hist.low[-1] < lowest_prior_48
        if breakdown:
            # Close at next open
            if 'entry_price' in state:
                del state['entry_price']
                del state['entry_atr']
            return {"target": 0.0, "stop": None, "take": None}
        else:
            # Keep position, send take-profit order
            entry_price = state['entry_price']
            entry_atr = state['entry_atr']
            take = entry_price + 2 * entry_atr
            return {"target": pos, "stop": None, "take": take}

    else:
        # Short position (should not happen in long-only strategy)
        return {"target": 0.0, "stop": None, "take": None}
